const trigger = $('Execute Workflow Trigger').first().json;
const response = $input.first().json.message?.content || $input.first().json.content || '';
const jsonMatch = response.match(/```json\s*\n([\s\S]*?)```/);
const parsed = jsonMatch ? JSON.parse(jsonMatch[1].trim()) : JSON.parse(response);
if (parsed.event_date) parsed.event_date = new Date(parsed.event_date).toISOString().split('T')[0];
const rg = parsed.response_guidance || {};
if (!rg.must_include) rg.must_include = [];
if (!rg.should_avoid) rg.should_avoid = [];
if (!rg.suggested_actions) rg.suggested_actions = [];
const ctx = { ...parsed, response_guidance: rg, classification: trigger.classification };
return { json: ctx };
